    for (role, password) in [
        (PasswordRole::User, "user-r5"),
        (PasswordRole::Owner, "owner-r5"),
    ] {
        let key = derive(R5, role, password).unwrap();
        assert_eq!(key.as_bytes(), R5_KEY);
